const cx = 540, cy = 1180, s = 84, cos = Math.cos(Math.PI / 6);
const iso = (x, y, z) => [cx + (x - y) * s * cos, cy + (x + y) * s * .5 - z * s];
const pts = a => a.map(p => p.join(',')).join(' ');
const box = (x, y, z, w, d, h, c) => { const [t, l, r] = c;
  const A = iso(x, y, z + h), B = iso(x + w, y, z + h), C = iso(x + w, y + d, z + h), D = iso(x, y + d, z + h), Bb = iso(x + w, y, z), Cb = iso(x + w, y + d, z), Db = iso(x, y + d, z);
  return `<g><polygon points="${pts([D, C, Cb, Db])}" fill="${l}"/><polygon points="${pts([C, B, Bb, Cb])}" fill="${r}"/><polygon points="${pts([A, B, C, D])}" fill="${t}"/></g>`; };
const B = ['#748ffc', '#4c6ef5', '#3b5bdb'], R = ['#ffa98e', '#ff8a65', '#f4704a'], M = ['#96f2d7', '#63e6be', '#38d9a9'], G = ['#ffffff', '#dfe4ee', '#c9d0de'];
let g = box(-4, -4, -.3, 8, 8, .3, G);
g += box(-3, -3, 0, 2, 2, 3, B) + box(-3, 1, 0, 2, 2, 1.6, M) + box(1, -3, 0, 2, 2, 2.2, R) + box(1.2, 1.2, 0, 1.6, 1.6, .8, B);
const flow = pts([iso(-2, -1, .2), iso(-2, 2, .2), iso(2, 2, .2), iso(2, -1, .2)]);
const svg = E('inset:0');
svg.innerHTML = `<svg width="1080" height="1920">${g}<polyline points="${flow}" fill="none" stroke="#1f2a44" stroke-width="10" stroke-dasharray="26 22" stroke-linecap="round"/></svg>`;
const gs = svg.querySelectorAll('g'); const fl = svg.querySelector('polyline');
E('left:80px;top:220px;width:920px;font:700 120px/1 Poppins;color:#1f2a44', 'Veri nasıl<br>akar?');
for (const [x, y, t] of [[150, 620, 'Sunucu'], [700, 760, 'İşlemci'], [130, 1330, 'Depo']]) { E(`left:${x}px;top:${y}px;padding:14px 26px;background:#fff;border-radius:14px;box-shadow:0 6px 0 #c9d0de;font:700 46px/1 Poppins;color:#1f2a44`, t); }
gs.forEach((e, i) => i && tl.from(e, {y: -260, opacity: 0, duration: .55, ease: 'back.out(1.2)'}, .1 + i * .18));
tl.fromTo(fl, {strokeDashoffset: 0}, {strokeDashoffset: -240, duration: 2.6, ease: 'none'}, 0);
